import * as T from './vendor/three.module.js';
import {roundedBox} from './rounded-geometry.js';
export function chapterTwoMaterials(){const materials=[],maps=new Map(),cache=new Map();let loaded=false;
 function apply(m){const base=maps.get(m.userData.atlasCell);if(!base)return;m.map=base;if(m.userData.tile>1&&base.userData.cropped){m.map=base.clone();m.map.wrapS=m.map.wrapT=T.RepeatWrapping;m.map.repeat.setScalar(m.userData.tile)}m.needsUpdate=true}function material(cell,color=0xffffff,extra={}){const key=cell+'|'+color+'|'+JSON.stringify(extra);if(cache.has(key))return cache.get(key);const {tile=1,...rest}=extra;const m=new T.MeshStandardMaterial({color,roughness:.85,...rest});m.userData.atlasCell=cell;m.userData.tile=tile;materials.push(m);cache.set(key,m);apply(m);return m}
 async function load(){if(loaded)return;loaded=true;try{const atlas=await new T.TextureLoader().loadAsync('./assets/chapter2-atlas.webp');atlas.colorSpace=T.SRGBColorSpace;atlas.anisotropy=4;for(let i=0;i<16;i++){let t;if(atlas.image&&typeof document!=='undefined'&&document.createElement){const c=document.createElement('canvas');if(c.getContext){c.width=c.height=256;c.getContext('2d').drawImage(atlas.image,(i%4)*atlas.image.width/4,Math.floor(i/4)*atlas.image.height/4,atlas.image.width/4,atlas.image.height/4,0,0,256,256);t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.userData.cropped=true}}if(!t){t=atlas.clone();t.repeat.set(.25,.25);t.offset.set((i%4)/4,1-(Math.floor(i/4)+1)/4)}maps.set(i,t)}for(const m of materials)apply(m)}catch{loaded=false}}
 return {material,load,materials};}
export function citizenModel(parent,x,z,{id,name,role='citizen',woman=false,cloth=5,skin=0,scale=1}={},palette){
 const g=new T.Group();g.position.set(x,0,z);g.scale.setScalar(scale);parent.add(g);const body=palette.material(cloth),face=palette.material(skin,0xe9d3bd),leather=palette.material(2),steel=palette.material(8,0x9aafbb),hair=palette.material(2,role==='elder'?0xd9d0bd:0x584230),dark=new T.MeshStandardMaterial({color:0x101a24}),glow=new T.MeshBasicMaterial({color:role==='vampire'?0xff4458:0xc3edff});
 function mesh(geo,m,x,y,z,p=g){const o=new T.Mesh(geo,m);o.position.set(x,y,z);p.add(o);return o}
 const torso=mesh(roundedBox(.48,.64,.28),body,0,1.18,0);const head=mesh(new T.SphereGeometry(.19,12,10),face,0,1.76,0);head.scale.set(.9,1.1,.92);mesh(new T.SphereGeometry(.2,10,8),hair,0,1.84,-.025).scale.set(1,.6,.9);for(const side of [-1,1]){mesh(new T.SphereGeometry(.023,6,5),dark,side*.065,1.79,.163);mesh(new T.ConeGeometry(.035,.075,5),face,0,1.72,.185).rotation.x=Math.PI/2;const brow=mesh(roundedBox(.09,.02,.02),hair,side*.067,1.83,.16);brow.rotation.z=-side*.13}
 mesh(roundedBox(.5,.07,.31),leather,0,.94,0);mesh(roundedBox(.08,.09,.025),steel,0,.94,.17);
 if(woman){mesh(new T.ConeGeometry(.37,.7,10),body,0,.59,0);for(const side of [-1,1]){const braid=mesh(new T.CapsuleGeometry(.04,.23,3,6),hair,side*.17,1.63,-.035);braid.rotation.z=side*.16}}
 const arms=[],legs=[];for(const side of [-1,1]){const leg=new T.Group();leg.position.set(side*.13,.9,0);g.add(leg);mesh(new T.CapsuleGeometry(.095,.48,4,8),leather,0,-.3,0,leg);mesh(roundedBox(.18,.13,.3),leather,0,-.78,.055,leg);legs.push(leg);const arm=new T.Group();arm.position.set(side*.29,1.46,0);g.add(arm);mesh(new T.CapsuleGeometry(.075,.36,4,8),body,0,-.25,0,arm);mesh(new T.SphereGeometry(.085,8,6),face,0,-.51,0,arm);arms.push(arm)}
 const prop=new T.Group();arms[1].add(prop);prop.position.set(0,-.52,.03);
 if(['guard','captain','order','sword','warden'].includes(role)){const blade=mesh(roundedBox(.055,.65,.035),steel,0,.3,0,prop);mesh(roundedBox(.22,.035,.06),steel,0,0,0,prop);mesh(new T.CapsuleGeometry(.035,.16,3,6),leather,0,-.1,0,prop);if(role==='captain'||role==='order'){mesh(new T.ConeGeometry(.23,.3,8),steel,0,2.01,0);mesh(new T.CapsuleGeometry(.055,.33,3,6),palette.material(4),0,2.16,-.02)}}
 if(role==='crossbow'){prop.rotation.y=Math.PI;mesh(roundedBox(.07,.08,.7),leather,0,0,-.23,prop);mesh(roundedBox(.55,.035,.045),steel,0,0,-.43,prop);const line=new T.Line(new T.BufferGeometry().setFromPoints([new T.Vector3(-.26,0,-.43),new T.Vector3(0,0,-.1),new T.Vector3(.26,0,-.43)]),new T.LineBasicMaterial({color:0xcdbf97}));prop.add(line)}
 if(['mage','vampire'].includes(role)){mesh(new T.CylinderGeometry(.025,.035,1.3,7),leather,0,.25,0,prop);mesh(new T.OctahedronGeometry(.12),glow,0,.95,0,prop);const cape=mesh(new T.ConeGeometry(.42,1.25,12,1,true),body,0,1.08,-.15);cape.scale.z=.5;if(role==='vampire'){head.material=palette.material(1,0xb9c6d0);for(const side of [-1,1]){mesh(new T.SphereGeometry(.025,7,5),glow,side*.065,1.79,.18);mesh(new T.ConeGeometry(.014,.06,5),palette.material(9),side*.06,1.65,.17).rotation.z=Math.PI}}}
 if(role==='smith'){mesh(new T.CylinderGeometry(.04,.04,.3,7),leather,0,.15,0,prop);mesh(roundedBox(.24,.12,.1),steel,0,.32,0,prop)}
 if(role==='merchant'||role==='courier'){mesh(roundedBox(.24,.3,.10),leather,.25,1.04,.06);mesh(roundedBox(.07,.65,.04),leather,0,1.3,.17).rotation.z=-.55}
 if(role==='cook'){mesh(roundedBox(.3,.55,.02),palette.material(5,0xdfd0ab),0,1.12,.16);mesh(new T.CylinderGeometry(.19,.16,.18,10),palette.material(5,0xe8dac0),0,2.02,0)}
 let clock=0,attack=0,kind='sword',moving=false,previous=g.position.clone();const n={g,id,name,role,woman,species:role==='vampire'?'vampire':'cultist-'+role,height:1.95,heading:0,home:new T.Vector3(x,0,z),target:new T.Vector3(x,0,z),timer:0,cooldown:1,hp:1,maxHp:1,generation:0,hit:false,chapterTwo:true};
 function pose(dt){clock+=dt;attack=Math.max(0,attack-dt);moving=g.position.distanceToSquared(previous)>.000001;previous.copy(g.position);g.rotation.y=n.heading;const swing=moving?Math.sin(clock*7)*.38:Math.sin(clock*1.8)*.025;legs.forEach((o,i)=>o.rotation.x=woman?swing*.45*(i?-1:1):swing*(i?-1:1));arms.forEach((o,i)=>{o.rotation.x=-swing*(i?-1:1);o.rotation.z=(i?-.08:.08)});if(attack>0){const phase=1-attack/.7;arms[1].rotation.x=kind==='crossbow'?-.8:kind==='mage'?-1.2:phase<.45?phase*3:-1.8*Math.sin((phase-.45)/.55*Math.PI);if(kind==='crossbow'||kind==='mage')arms[0].rotation.x=-.65}if(role==='smith'&&!moving&&!attack)arms[1].rotation.x=-.4-Math.max(0,Math.sin(clock*2.5))*1.1;if(role==='crossbow'&&!attack){arms[1].rotation.x=-.5;prop.rotation.x=.12}}
 n.update=pose;n.animate=()=>{};n.cueAttack=(type,duration=.7)=>{kind=type;attack=.7};g.userData.arms=arms;return n;
}
